INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-19-01', 'lesson-essential-verbs-a1-19', 1, 'sentence', 'The class begins at nine.', 'A aula começa às nove.', '/ðə klæs bɪˈɡɪnz æt naɪn/', '"Begin" = começar (um pouco mais formal que "start"). Com he/she/it: "begins".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"class","pos":"noun","ipa":"/klæs/","gloss":"aula, turma"},{"surface":"begins","pos":"verb","ipa":"/bɪˈɡɪnz/","gloss":"começa"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-02', 'lesson-essential-verbs-a1-19', 2, 'sentence', 'It began to rain.', 'Começou a chover.', '/ɪt bɪˈɡæn tuː reɪn/', 'Passado irregular: "began". "Begin to" + verbo.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"began","pos":"verb","ipa":"/bɪˈɡæn/","gloss":"começou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-03', 'lesson-essential-verbs-a1-19', 3, 'sentence', 'The show will begin soon.', 'O show vai começar logo.', '/ðə ʃoʊ wɪl bɪˈɡɪn suːn/', 'Futuro com "will".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"begin","pos":"verb","ipa":"/bɪˈɡɪn/","gloss":"começar"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-04', 'lesson-essential-verbs-a1-19', 4, 'sentence', 'Has the meeting begun?', 'A reunião já começou?', '/hæz ðə ˈmiːtɪŋ bɪˈɡʌn/', 'Particípio irregular: "begun". Sequência: begin, began, begun.', '[]'::jsonb, '[{"surface":"Has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"begun","pos":"verb","ipa":"/bɪˈɡʌn/","gloss":"começado"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-05', 'lesson-essential-verbs-a1-19', 5, 'sentence', 'You seem happy today.', 'Você parece feliz hoje.', '/juː siːm ˈhæpi təˈdeɪ/', '"Seem" + adjetivo = parecer (impressão). Parecido com "look", mas não só pela aparência.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"seem","pos":"verb","ipa":"/siːm/","gloss":"parecer"},{"surface":"happy","pos":"adjective","ipa":"/ˈhæpi/","gloss":"feliz"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-06', 'lesson-essential-verbs-a1-19', 6, 'sentence', 'It seemed like a good idea.', 'Pareceu uma boa ideia.', '/ɪt siːmd laɪk ə ɡʊd aɪˈdiːə/', '"Seem like" + substantivo. Passado regular: "seemed".', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"seemed","pos":"verb","ipa":"/siːmd/","gloss":"pareceu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"idea","pos":"noun","ipa":"/aɪˈdiːə/","gloss":"ideia"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-07', 'lesson-essential-verbs-a1-19', 7, 'sentence', 'This will seem strange at first.', 'Isso vai parecer estranho no começo.', '/ðɪs wɪl siːm streɪndʒ æt fɜːrst/', '"At first" = no começo.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"seem","pos":"verb","ipa":"/siːm/","gloss":"parecer"},{"surface":"strange","pos":"adjective","ipa":"/streɪndʒ/","gloss":"estranho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"first","pos":"adjective","ipa":"/fɜːrst/","gloss":"primeiro"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-19-08', 'lesson-essential-verbs-a1-19', 8, 'sentence', 'Things have seemed calm lately.', 'As coisas têm parecido calmas ultimamente.', '/θɪŋz hæv siːmd kɑːm ˈleɪtli/', 'Present perfect + "lately" = ultimamente.', '[]'::jsonb, '[{"surface":"Things","pos":"noun","ipa":"/θɪŋz/","gloss":"coisas"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"seemed","pos":"verb","ipa":"/siːmd/","gloss":"pareceu"},{"surface":"calm","pos":"adjective","ipa":"/kɑːm/","gloss":"calmo"},{"surface":"lately","pos":"adverb","ipa":"/ˈleɪtli/","gloss":"ultimamente"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-20-01', 'lesson-essential-verbs-a1-20', 1, 'sentence', 'Can you help me?', 'Você pode me ajudar?', '/kæn juː hɛlp miː/', '"Help" + pessoa, sem preposição: "help me".', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-02', 'lesson-essential-verbs-a1-20', 2, 'sentence', 'She helped me with my homework.', 'Ela me ajudou com a lição.', '/ʃiː hɛlpt miː wɪð maɪ ˈhoʊmwɜːrk/', '"Help with" + tarefa. Passado regular: "helped" (/t/).', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"with","pos":"preposition","ipa":"/wɪð/","gloss":"com"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"homework","pos":"noun","ipa":"/ˈhoʊmwɜːrk/","gloss":"lição de casa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-03', 'lesson-essential-verbs-a1-20', 3, 'sentence', 'This will help you sleep.', 'Isso vai te ajudar a dormir.', '/ðɪs wɪl hɛlp juː sliːp/', '"Help" + pessoa + verbo base, sem "to": "help you sleep".', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-04', 'lesson-essential-verbs-a1-20', 4, 'sentence', 'You have helped me a lot.', 'Você me ajudou muito.', '/juː hæv hɛlpt miː ə lɑːt/', 'Present perfect com efeito no presente (gratidão agora).', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-05', 'lesson-essential-verbs-a1-20', 5, 'sentence', 'We talk every week.', 'A gente conversa toda semana.', '/wiː tɔːk ˈɛvri wiːk/', '"Talk" = conversar. "Talk to" + pessoa, "talk about" + assunto.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-06', 'lesson-essential-verbs-a1-20', 6, 'sentence', 'I talked to the manager.', 'Falei com o gerente.', '/aɪ tɔːkt tuː ðə ˈmænɪdʒər/', '"Talk to" = falar com. Passado regular: "talked" (/t/, o "l" é mudo).', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"talked","pos":"verb","ipa":"/tɔːkt/","gloss":"conversou"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"manager","pos":"noun","ipa":"/ˈmænɪdʒər/","gloss":"gerente"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-07', 'lesson-essential-verbs-a1-20', 7, 'sentence', 'We''ll talk about it later.', 'A gente conversa sobre isso depois.', '/wiːl tɔːk əˈbaʊt ɪt ˈleɪtər/', '"Talk about" = falar sobre. Futuro contraído: "we''ll".', '[]'::jsonb, '[{"surface":"We''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"later","pos":"adverb","ipa":"/ˈleɪtər/","gloss":"mais tarde"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-20-08', 'lesson-essential-verbs-a1-20', 8, 'sentence', 'We haven''t talked in years.', 'Faz anos que não conversamos.', '/wiː ˈhævənt tɔːkt ɪn jɪrz/', 'Present perfect negativo + "in years" = há anos.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"talked","pos":"verb","ipa":"/tɔːkt/","gloss":"conversou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-21-01', 'lesson-essential-verbs-a1-21', 1, 'sentence', 'Turn left at the corner.', 'Vire à esquerda na esquina.', '/tɜːrn lɛft æt ðə ˈkɔːrnər/', '"Turn left/right" = virar.', '[]'::jsonb, '[{"surface":"Turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"corner","pos":"noun","ipa":"/ˈkɔːrnər/","gloss":"esquina"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-02', 'lesson-essential-verbs-a1-21', 2, 'sentence', 'She turned off the lights.', 'Ela apagou as luzes.', '/ʃiː tɜːrnd ɔːf ðə laɪts/', '"Turn off" = desligar, apagar; "turn on" = ligar, acender.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"off","pos":"particle","ipa":"/ɔːf/","gloss":"(partícula: off)"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"lights","pos":"noun","ipa":"/laɪts/","gloss":"luzes"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-03', 'lesson-essential-verbs-a1-21', 3, 'sentence', 'I will turn thirty next month.', 'Vou fazer trinta anos mês que vem.', '/aɪ wɪl tɜːrn ˈθɜːrti nɛkst mʌnθ/', '"Turn" + idade = fazer anos.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-04', 'lesson-essential-verbs-a1-21', 4, 'sentence', 'The weather has turned cold.', 'O tempo esfriou.', '/ðə ˈwɛðər hæz tɜːrnd koʊld/', '"Turn" + adjetivo = ficar (mudança).', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"weather","pos":"noun","ipa":"/ˈwɛðər/","gloss":"tempo, clima"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-05', 'lesson-essential-verbs-a1-21', 5, 'sentence', 'I start work at nine.', 'Começo a trabalhar às nove.', '/aɪ stɑːrt wɜːrk æt naɪn/', '"Start" = começar. "Start work" sem artigo.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"nine","pos":"numeral","ipa":"/naɪn/","gloss":"nove"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-06', 'lesson-essential-verbs-a1-21', 6, 'sentence', 'It started to snow.', 'Começou a nevar.', '/ɪt ˈstɑːrtɪd tuː snoʊ/', 'Passado regular: "started" (/ɪd/ depois de "t").', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"snow","pos":"verb","ipa":"/snoʊ/","gloss":"nevar; neve"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-07', 'lesson-essential-verbs-a1-21', 7, 'sentence', 'The car will not start.', 'O carro não quer pegar.', '/ðə kɑːr wɪl nɑːt stɑːrt/', '"Start" também é dar partida. "Will not" aqui mostra recusa: não quer.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-21-08', 'lesson-essential-verbs-a1-21', 8, 'sentence', 'Have you started the new book?', 'Você já começou o livro novo?', '/hæv juː ˈstɑːrtɪd ðə nuː bʊk/', 'Present perfect em pergunta sobre algo recente.', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"book","pos":"verb","ipa":"/bʊk/","gloss":"reservar; livro"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-22-01', 'lesson-essential-verbs-a1-22', 1, 'sentence', 'Show me your ticket, please.', 'Mostre sua passagem, por favor.', '/ʃoʊ miː jʊr ˈtɪkɪt pliːz/', '"Show" + pessoa + coisa: "show me your ticket".', '[]'::jsonb, '[{"surface":"Show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"ticket","pos":"noun","ipa":"/ˈtɪkɪt/","gloss":"passagem, bilhete"},{"surface":"please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-02', 'lesson-essential-verbs-a1-22', 2, 'sentence', 'He showed us around the city.', 'Ele nos mostrou a cidade.', '/hiː ʃoʊd ʌs əˈraʊnd ðə ˈsɪti/', '"Show around" = levar para conhecer. Passado regular: "showed".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"showed","pos":"verb","ipa":"/ʃoʊd/","gloss":"mostrou"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"around","pos":"adverb","ipa":"/əˈraʊnd/","gloss":"ao redor, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"city","pos":"noun","ipa":"/ˈsɪti/","gloss":"cidade"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-03', 'lesson-essential-verbs-a1-22', 3, 'sentence', 'I''ll show you how it works.', 'Vou te mostrar como funciona.', '/aɪl ʃoʊ juː haʊ ɪt wɜːrks/', '"Show you how" + frase = mostrar como.', '[]'::jsonb, '[{"surface":"I''ll","pos":"pronoun","ipa":"/aɪl/","gloss":"eu vou"},{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"how","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"works","pos":"verb","ipa":"/wɜːrks/","gloss":"funciona, serve"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-04', 'lesson-essential-verbs-a1-22', 4, 'sentence', 'The results have shown a big change.', 'Os resultados mostraram uma grande mudança.', '/ðə rɪˈzʌlts hæv ʃoʊn ə bɪɡ tʃeɪndʒ/', 'Particípio irregular: "shown" (também aceito "showed").', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"results","pos":"noun","ipa":"/rɪˈzʌlts/","gloss":"resultados"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"shown","pos":"verb","ipa":"/ʃoʊn/","gloss":"mostrado"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"},{"surface":"change","pos":"verb","ipa":"/tʃeɪndʒ/","gloss":"trocar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-05', 'lesson-essential-verbs-a1-22', 5, 'sentence', 'I can''t hear you.', 'Não estou te ouvindo.', '/aɪ kænt hɪr juː/', '"Hear" = ouvir (sem esforço); "listen" = escutar com atenção. Com "can" para percepção.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"can''t","pos":"auxiliary verb","ipa":"/kænt/","gloss":"não poder"},{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-06', 'lesson-essential-verbs-a1-22', 6, 'sentence', 'I heard a noise last night.', 'Ouvi um barulho ontem à noite.', '/aɪ hɜːrd ə nɔɪz læst naɪt/', 'Passado irregular: "heard" /hɜːrd/.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"heard","pos":"verb","ipa":"/hɜːrd/","gloss":"ouviu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"},{"surface":"last","pos":"adjective","ipa":"/læst/","gloss":"último"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-07', 'lesson-essential-verbs-a1-22', 7, 'sentence', 'You will hear from us soon.', 'Você vai ter notícias nossas em breve.', '/juː wɪl hɪr frʌm ʌs suːn/', '"Hear from" = ter notícias de.', '[]'::jsonb, '[{"surface":"You","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-22-08', 'lesson-essential-verbs-a1-22', 8, 'sentence', 'Have you heard the news?', 'Você soube da notícia?', '/hæv juː hɜːrd ðə nuːz/', '"News" é incontável e singular: "the news is".', '[]'::jsonb, '[{"surface":"Have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"heard","pos":"verb","ipa":"/hɜːrd/","gloss":"ouviu"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-23-01', 'lesson-essential-verbs-a1-23', 1, 'sentence', 'My kids play soccer on Saturdays.', 'Meus filhos jogam futebol aos sábados.', '/maɪ kɪdz pleɪ ˈsɑːkər ɑːn ˈsætərdeɪz/', '"Play" + esporte, sem artigo: "play soccer".', '[]'::jsonb, '[{"surface":"My","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"kids","pos":"noun","ipa":"/kɪdz/","gloss":"crianças, filhos"},{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"},{"surface":"soccer","pos":"noun","ipa":"/ˈsɑːkər/","gloss":"futebol"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Saturdays","pos":"proper noun","ipa":"/ˈsætərdeɪz/","gloss":"sábados"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-02', 'lesson-essential-verbs-a1-23', 2, 'sentence', 'She played the piano at the party.', 'Ela tocou piano na festa.', '/ʃiː pleɪd ðə piˈænoʊ æt ðə ˈpɑːrti/', '"Play" + instrumento, com "the": "play the piano".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"played","pos":"verb","ipa":"/pleɪd/","gloss":"jogou, tocou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"piano","pos":"noun","ipa":"/piˈænoʊ/","gloss":"piano"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"party","pos":"noun","ipa":"/ˈpɑːrti/","gloss":"festa"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-03', 'lesson-essential-verbs-a1-23', 3, 'sentence', 'We''ll play a game after dinner.', 'Vamos jogar um jogo depois do jantar.', '/wiːl pleɪ ə ɡeɪm ˈæftər ˈdɪnər/', 'Futuro contraído: "we''ll".', '[]'::jsonb, '[{"surface":"We''ll","pos":"pronoun","ipa":"/wiːl/","gloss":"nós vamos (we will)"},{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"game","pos":"noun","ipa":"/ɡeɪm/","gloss":"jogo"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-04', 'lesson-essential-verbs-a1-23', 4, 'sentence', 'I haven''t played in years.', 'Faz anos que não jogo.', '/aɪ ˈhævənt pleɪd ɪn jɪrz/', 'Present perfect negativo + "in years".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"haven''t","pos":"verb","ipa":"/ˈhævənt/","gloss":"não (have not)"},{"surface":"played","pos":"verb","ipa":"/pleɪd/","gloss":"jogou, tocou"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-05', 'lesson-essential-verbs-a1-23', 5, 'sentence', 'I run in the park every morning.', 'Corro no parque toda manhã.', '/aɪ rʌn ɪn ðə pɑːrk ˈɛvri ˈmɔːrnɪŋ/', '"Run" = correr. Hábito com "every morning".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"park","pos":"verb","ipa":"/pɑːrk/","gloss":"estacionar"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-06', 'lesson-essential-verbs-a1-23', 6, 'sentence', 'We ran to catch the bus.', 'Corremos para pegar o ônibus.', '/wiː ræn tuː kætʃ ðə bʌs/', 'Passado irregular: "ran". "Catch the bus" = pegar o ônibus.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"catch","pos":"verb","ipa":"/kætʃ/","gloss":"pegar, apanhar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"bus","pos":"noun","ipa":"/bʌs/","gloss":"ônibus"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-07', 'lesson-essential-verbs-a1-23', 7, 'sentence', 'She will run the company one day.', 'Um dia ela vai comandar a empresa.', '/ʃiː wɪl rʌn ðə ˈkʌmpəni wʌn deɪ/', '"Run" também é administrar, dirigir.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"company","pos":"noun","ipa":"/ˈkʌmpəni/","gloss":"empresa"},{"surface":"one","pos":"pronoun","ipa":"/wʌn/","gloss":"uma (I owe you one)"},{"surface":"day","pos":"noun","ipa":"/deɪ/","gloss":"dia"}]'::jsonb, NULL, NULL),
  ('unit-essential-verbs-a1-23-08', 'lesson-essential-verbs-a1-23', 8, 'sentence', 'We have run out of milk.', 'Acabou o leite.', '/wiː hæv rʌn aʊt ʌv mɪlk/', '"Run out of" = ficar sem. Particípio igual à base: "run".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"milk","pos":"noun","ipa":"/mɪlk/","gloss":"leite"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-24-01', 'lesson-essential-verbs-a1-24', 1, 'verb_forms', 'begin began begun', 'começar', '/bɪˈɡɪn bɪˈɡæn bɪˈɡʌn/', 'Base "begin" · passado "began" · particípio "begun".', '[]'::jsonb, '[{"surface":"begin","pos":"verb","ipa":"/bɪˈɡɪn/","gloss":"começar"},{"surface":"began","pos":"verb","ipa":"/bɪˈɡæn/","gloss":"começou"},{"surface":"begun","pos":"verb","ipa":"/bɪˈɡʌn/","gloss":"começado"}]'::jsonb, 'It began to rain.', 'Começou a chover.'),
  ('unit-essential-verbs-a1-24-02', 'lesson-essential-verbs-a1-24', 2, 'verb_forms', 'seem seemed seemed', 'parecer', '/siːm siːmd siːmd/', 'Regular: "-ed" soa /d/.', '[]'::jsonb, '[{"surface":"seem","pos":"verb","ipa":"/siːm/","gloss":"parecer"},{"surface":"seemed","pos":"verb","ipa":"/siːmd/","gloss":"pareceu"},{"surface":"seemed","pos":"verb","ipa":"/siːmd/","gloss":"pareceu"}]'::jsonb, 'It seemed like a good idea.', 'Pareceu uma boa ideia.'),
  ('unit-essential-verbs-a1-24-03', 'lesson-essential-verbs-a1-24', 3, 'verb_forms', 'help helped helped', 'ajudar', '/hɛlp hɛlpt hɛlpt/', 'Regular: "-ed" soa /t/.', '[]'::jsonb, '[{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"},{"surface":"helped","pos":"verb","ipa":"/hɛlpt/","gloss":"ajudou"}]'::jsonb, 'She helped me with my homework.', 'Ela me ajudou com a lição.'),
  ('unit-essential-verbs-a1-24-04', 'lesson-essential-verbs-a1-24', 4, 'verb_forms', 'talk talked talked', 'conversar', '/tɔːk tɔːkt tɔːkt/', 'Regular: "-ed" soa /t/; o "l" é mudo.', '[]'::jsonb, '[{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"},{"surface":"talked","pos":"verb","ipa":"/tɔːkt/","gloss":"conversou"},{"surface":"talked","pos":"verb","ipa":"/tɔːkt/","gloss":"conversou"}]'::jsonb, 'I talked to the manager.', 'Falei com o gerente.'),
  ('unit-essential-verbs-a1-24-05', 'lesson-essential-verbs-a1-24', 5, 'verb_forms', 'turn turned turned', 'virar, ligar', '/tɜːrn tɜːrnd tɜːrnd/', 'Regular: "-ed" soa /d/.', '[]'::jsonb, '[{"surface":"turn","pos":"verb","ipa":"/tɜːrn/","gloss":"ligar (turn on)"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"},{"surface":"turned","pos":"verb","ipa":"/tɜːrnd/","gloss":"virou, ficou"}]'::jsonb, 'She turned off the lights.', 'Ela apagou as luzes.'),
  ('unit-essential-verbs-a1-24-06', 'lesson-essential-verbs-a1-24', 6, 'verb_forms', 'start started started', 'começar', '/stɑːrt ˈstɑːrtɪd ˈstɑːrtɪd/', 'Regular: "-ed" soa /ɪd/ depois de "t".', '[]'::jsonb, '[{"surface":"start","pos":"verb","ipa":"/stɑːrt/","gloss":"começar"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"},{"surface":"started","pos":"verb","ipa":"/ˈstɑːrtɪd/","gloss":"começado"}]'::jsonb, 'It started to snow.', 'Começou a nevar.'),
  ('unit-essential-verbs-a1-24-07', 'lesson-essential-verbs-a1-24', 7, 'verb_forms', 'show showed shown', 'mostrar', '/ʃoʊ ʃoʊd ʃoʊn/', 'Passado regular "showed"; particípio "shown".', '[]'::jsonb, '[{"surface":"show","pos":"verb","ipa":"/ʃoʊ/","gloss":"aparecer (show up)"},{"surface":"showed","pos":"verb","ipa":"/ʃoʊd/","gloss":"mostrou"},{"surface":"shown","pos":"verb","ipa":"/ʃoʊn/","gloss":"mostrado"}]'::jsonb, 'He showed us around the city.', 'Ele nos mostrou a cidade.'),
  ('unit-essential-verbs-a1-24-08', 'lesson-essential-verbs-a1-24', 8, 'verb_forms', 'hear heard heard', 'ouvir', '/hɪr hɜːrd hɜːrd/', 'Base "hear" /hɪr/ · passado e particípio "heard" /hɜːrd/.', '[]'::jsonb, '[{"surface":"hear","pos":"verb","ipa":"/hɪr/","gloss":"ouvir"},{"surface":"heard","pos":"verb","ipa":"/hɜːrd/","gloss":"ouviu"},{"surface":"heard","pos":"verb","ipa":"/hɜːrd/","gloss":"ouviu"}]'::jsonb, 'I heard a noise last night.', 'Ouvi um barulho ontem à noite.'),
  ('unit-essential-verbs-a1-24-09', 'lesson-essential-verbs-a1-24', 9, 'verb_forms', 'play played played', 'jogar, tocar', '/pleɪ pleɪd pleɪd/', 'Regular: "-ed" soa /d/.', '[]'::jsonb, '[{"surface":"play","pos":"verb","ipa":"/pleɪ/","gloss":"jogar, tocar, brincar"},{"surface":"played","pos":"verb","ipa":"/pleɪd/","gloss":"jogou, tocou"},{"surface":"played","pos":"verb","ipa":"/pleɪd/","gloss":"jogou, tocou"}]'::jsonb, 'She played the piano at the party.', 'Ela tocou piano na festa.'),
  ('unit-essential-verbs-a1-24-10', 'lesson-essential-verbs-a1-24', 10, 'verb_forms', 'run ran run', 'correr', '/rʌn ræn rʌn/', 'Base "run" · passado "ran" · particípio "run".', '[]'::jsonb, '[{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"run","pos":"verb","ipa":"/rʌn/","gloss":"correr; administrar"}]'::jsonb, 'We ran to catch the bus.', 'Corremos para pegar o ônibus.')
